/** Account as stored in QuickBooks Desktop. */
export interface Account {
  /** QuickBooks-assigned ID of this account. */
  id: string;
  /** Type of this object. */
  objectType: "qbd_account";
  /**
   * When this account was created, as an ISO 8601 date-time with the QuickBooks computer's UTC offset.
   *
   * ISO 8601 date-time with the offset QuickBooks reports.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  createdAt: string;
  /**
   * When this account was last changed, as an ISO 8601 date-time with the QuickBooks computer's UTC offset. Whole seconds: a second change within the same second keeps this value, so incremental syncs should overlap `updatedAfter` and deduplicate by `id` and `revisionNumber`.
   *
   * ISO 8601 date-time with the offset QuickBooks reports.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  updatedAt: string;
  /** Current revision of this account. Send it unchanged when updating; a stale value is rejected. QuickBooks changes it at most once per second, so a second edit within the same second keeps the same value. This API spaces its own consecutive writes to one object by over a second; edits made elsewhere in the same second are not detected. */
  revisionNumber: string;
  /** Name of this account, unique within its parent level. */
  name: string | null;
  /** Full hierarchical name of this account: parent names and its own name separated by colons. */
  fullName: string | null;
  /** Whether this account is active. Inactive objects stay in QuickBooks but are hidden from most lists. */
  isActive: boolean | null;
  /** Parent object one level up in the hierarchy, or null at the top level. */
  parent: Reference | null;
  /** Depth in the hierarchy: 0 for top-level objects, 1 for their children and so on. */
  sublevel: number | null;
  /**
   * Account type of this account.
   *
   * Open enum: new values can appear without an API version change.
   */
  accountType: AccountAccountType | null;
  /**
   * Special account type of this account.
   *
   * Open enum: new values can appear without an API version change.
   */
  specialAccountType: AccountSpecialAccountType | null;
  /** Account number for this account. */
  accountNumber: string | null;
  /** Bank account number of this account. */
  bankAccountNumber: string | null;
  /** Description of this account. */
  description: string | null;
  /**
   * Open balance of this account alone, as a decimal string.
   *
   * Decimal string (for example "52.75"); the SDK never converts it to a binary float.
   *
   * @example "1250.00"
   */
  balance: string | null;
  /**
   * Open balance including all child jobs, as a decimal string.
   *
   * Decimal string (for example "52.75"); the SDK never converts it to a binary float.
   *
   * @example "1250.00"
   */
  totalBalance: string | null;
  /** Tax line details details for this account. */
  taxLineDetails: TaxLineDetail | null;
  /**
   * Cash flow classification of this account.
   *
   * Open enum: new values can appear without an API version change.
   */
  cashFlowClassification: AccountCashFlowClassification | null;
  /** Currency of this account. */
  currency: Reference | null;
  /** Custom field values QuickBooks stores on this account. */
  customFields: CustomField[];
}

