export interface AccountList {
  /** Always `list`. */
  objectType: "list";
  /** The endpoint that produced this list. */
  url: "/v1/quickbooks-desktop/accounts";
  /** Every matching object. */
  data: Account[];
}

export interface AccountListParams {
  /** Return only the accounts with these QuickBooks IDs. Cannot be combined with fullNames, limit, status, updatedAfter, updatedBefore, nameStartsWith, nameContains, nameEndsWith, nameFrom, nameTo, accountType, currencyIds. */
  ids?: string[] | undefined;
  /** Return only the accounts with these full names (case-insensitive, including parent names separated by colons). Cannot be combined with ids, limit, status, updatedAfter, updatedBefore, nameStartsWith, nameContains, nameEndsWith, nameFrom, nameTo, accountType, currencyIds. */
  fullNames?: string[] | undefined;
  /** Maximum number of accounts to return. Cannot be combined with ids, fullNames. */
  limit?: number | undefined;
  /** Filter accounts by active state. Defaults to active ones only. Cannot be combined with ids, fullNames. */
  status?: ActiveStatus | undefined;
  /**
   * Return accounts changed on or after this date or date-time (QuickBooks local time unless an offset is given). Cannot be combined with ids, fullNames.
   *
   * Accepts YYYY-MM-DD or an ISO 8601 date-time.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  updatedAfter?: string | undefined;
  /**
   * Return accounts changed on or before this date or date-time (QuickBooks local time unless an offset is given). Cannot be combined with ids, fullNames.
   *
   * Accepts YYYY-MM-DD or an ISO 8601 date-time.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  updatedBefore?: string | undefined;
  /** Return accounts whose name starts with this text (case-insensitive). Cannot be combined with ids, fullNames, nameFrom, nameTo. */
  nameStartsWith?: string | undefined;
  /** Return accounts whose name contains this text (case-insensitive). Cannot be combined with ids, fullNames, nameFrom, nameTo. */
  nameContains?: string | undefined;
  /** Return accounts whose name ends with this text (case-insensitive). Cannot be combined with ids, fullNames, nameFrom, nameTo. */
  nameEndsWith?: string | undefined;
  /** Return accounts whose name sorts at or after this value. Cannot be combined with ids, fullNames, nameStartsWith, nameContains, nameEndsWith. */
  nameFrom?: string | undefined;
  /** Return accounts whose name sorts at or before this value. Cannot be combined with ids, fullNames, nameStartsWith, nameContains, nameEndsWith. */
  nameTo?: string | undefined;
  /** Filter by account type. Cannot be combined with ids, fullNames. */
  accountType?: AccountAccountType | undefined;
  /** Return only accounts in these currency IDs. Cannot be combined with ids, fullNames. */
  currencyIds?: string[] | undefined;
}

