export interface EndUser {
  /**
   * Unique identifier for the end user.
   *
   * @example "eu_01j9x4m6v4c8k2t7q0r5s3w1zb"
   */
  id: string;
  /** Always `end_user`. */
  objectType: "end_user";
  /**
   * When the end user was created. UTC, ISO 8601 with milliseconds.
   *
   * ISO 8601 date-time with the offset QuickBooks reports.
   *
   * @example "2026-10-05T16:03:59.002Z"
   */
  createdAt: string;
  /**
   * The end user's company name, shown in the setup flow.
   *
   * @example "Acme Supply"
   */
  companyName: string;
  /**
   * Your identifier for this end user. Unique within the project.
   *
   * @example "cust_8812"
   */
  sourceId: string;
  /**
   * Contact email, for your identification only. We never email end users.
   *
   * @example "ops@acme.example"
   */
  email: string;
  /** QuickBooks Desktop connections. Empty until the first auth session is created; at most one in v1. */
  integrationConnections: IntegrationConnection[];
}

/** An end user's QuickBooks Desktop connection with its Web Connector installs and company file mismatches. */
export interface EndUserConnection {
  /**
   * Unique identifier for the connection.
   *
   * @example "conn_01j9x4m6v4c8k2t7q0r5s3w1zc"
   */
  id: string;
  /** Always `integration_connection`. */
  objectType: "integration_connection";
  /**
   * When the connection was created. UTC, ISO 8601 with milliseconds.
   *
   * ISO 8601 date-time with the offset QuickBooks reports.
   *
   * @example "2026-10-05T16:03:59.002Z"
   */
  createdAt: string;
  /** The integration this connection uses. */
  integrationSlug: "quickbooks_desktop";
  /**
   * Derived connection status. `pending_setup`: no Web Connector has finished setup. `online`: the Web Connector checked in recently and the last QuickBooks session opened. `quickbooks_unavailable`: the Web Connector checks in but QuickBooks could not be opened (`statusReason` holds the error code). `company_file_mismatch`: a different company file is open. `offline`: no recent check-in. `disabled`: turned off by the developer.
   *
   * Open enum: new values can appear without an API version change.
   */
  status: EndUserConnectionStatus;
  /**
   * Code explaining a non-online status, when known: an error code (for example `QBD_ACCESS_NOT_GRANTED`), `QBD_QUICKBOOKS_NOT_RESPONDING` (the Web Connector checks in but QuickBooks does not answer, usually because a dialog is open) or `WEB_CONNECTOR_SCHEDULE_CHANGED`. With `online` it can be `QBD_FILE_MODE_CONFLICT`: QuickBooks reported a single-user/multi-user conflict and, for 2 minutes, the connection opens no session and synchronous requests fail fast with that code; or `WEB_CONNECTOR_SCHEDULE_CHANGED`.
   *
   * @example "QBD_QUICKBOOKS_NOT_RESPONDING"
   */
  statusReason: string | null;
  /** When the last request for this connection was made. UTC, ISO 8601. */
  lastRequestAt: string | null;
  /** When the last request succeeded. UTC, ISO 8601. */
  lastSuccessfulRequestAt: string | null;
  /** When the Web Connector last checked in. UTC, ISO 8601. */
  lastHeartbeatAt: string | null;
  /** The connected company file, once a session has opened. */
  companyFile: EndUserConnectionCompanyFile | null;
  /**
   * Whether QuickBooks lets this connection read personal data (employee Social Security numbers, payroll details), as the Web Connector reported in the last verified session. `denied`: QuickBooks omits those fields, and employee responses carry a `QBD_PERSONAL_DATA_WITHHELD` warning for each one. `unknown`: no session has reported it yet. The QuickBooks Admin changes it under Edit > Preferences > Integrated Applications > Company Preferences > Properties; the new value shows after the next session.
   *
   * Open enum: new values can appear without an API version change.
   *
   * @example "allowed"
   */
  personalDataAccess: EndUserConnectionPersonalDataAccess;
  /**
   * Unique identifier for the end user.
   *
   * @example "eu_01j9x4m6v4c8k2t7q0r5s3w1zb"
   */
  endUserId: string;
  /** Whether the connection is disabled. A disabled connection refuses Web Connector check-ins and fails new requests with `INTEGRATION_CONNECTION_DISABLED`. */
  disabled: boolean;
  /**
   * When the first Web Connector install finished setup, or null. UTC, ISO 8601 with milliseconds.
   *
   * ISO 8601 date-time with the offset QuickBooks reports.
   *
   * @example "2026-10-05T16:03:59.002Z"
   */
  setupCompletedAt: string | null;
  /** Web Connector installs (connector files) issued for this connection, newest first, at most 20. */
  installs: WebConnectorInstall[];
  /** Company file mismatches in the last 30 days. `total` is 0 when there were none. */
  companyFileMismatches: EndUserConnectionCompanyFileMismatches;
}

/** The connected company file, once a session has opened. */
export interface EndUserConnectionCompanyFile {
  /** Company name reported by QuickBooks. */
  companyName: string | null;
  /**
   * QuickBooks product and version reported by QuickBooks.
   *
   * @example "QuickBooks Enterprise Solutions: General Business 24.0"
   */
  product: string | null;
  /**
   * qbXML version used with this company file.
   *
   * @example "16.0"
   */
  qbxmlVersion: string | null;
  /**
   * QuickBooks edition country.
   *
   * @example "US"
   */
  country: string | null;
}

/** Company file mismatches in the last 30 days. `total` is 0 when there were none. */
export interface EndUserConnectionCompanyFileMismatches {
  /** Sessions in the last 30 days in which QuickBooks had a different company file open. */
  total: number;
  /** Grouped by the company file QuickBooks reported, most recent first. */
  groups: CompanyFileMismatch[];
}

export interface EndUserCreateInput {
  /**
   * The end user's company name, shown in the setup flow. 1–255 characters.
   *
   * @example "Acme Supply"
   */
  companyName: string;
  /**
   * Your identifier for this end user, unique within the project. 1–255 characters.
   *
   * @example "cust_8812"
   */
  sourceId: string;
  /**
   * Contact email for your identification. We never email end users.
   *
   * @example "ops@acme.example"
   */
  email: string;
}

export interface EndUserDeleted {
  /**
   * Unique identifier for the end user.
   *
   * @example "eu_01j9x4m6v4c8k2t7q0r5s3w1zb"
   */
  id: string;
  /** Always `end_user`. */
  objectType: "end_user";
  /** Always `true`. */
  deleted: true;
}

export interface EndUserListParams {
  /** The `nextCursor` from the previous page. */
  cursor?: string | undefined;
  /**
   * Page size, 1–100. Default 50.
   *
   * @defaultValue 50
   * @example 50
   */
  limit?: number | undefined;
}

export interface EndUserResetCompanyFileInput {
  /** `path`: forget the stored company file location (the file was moved or renamed on disk); the next session uses the file open in QuickBooks. `identity`: also forget the company identity (the company was renamed, or the end user deliberately switched to another file); the next session that QuickBooks answers becomes the connected company file. */
  mode: EndUserResetCompanyFileInputMode;
  /** Must be `reset_company_file`. Confirms you checked with the end user which company file is correct: with `identity`, whatever file is open next is accepted. */
  confirm: "reset_company_file";
}

export interface EndUserUpdateInput {
  /**
   * The end user's company name, shown in the setup flow. 1–255 characters.
   *
   * @example "Acme Supply"
   */
  companyName?: string | undefined;
  /**
   * Your identifier for this end user, unique within the project. 1–255 characters.
   *
   * @example "cust_8812"
   */
  sourceId?: string | undefined;
  /**
   * Contact email for your identification. We never email end users.
   *
   * @example "ops@acme.example"
   */
  email?: string | undefined;
}

export interface EntityListParams {
  /** Return only the entities with these QuickBooks IDs. Cannot be combined with fullNames, status, updatedAfter, updatedBefore, nameStartsWith, nameContains, nameEndsWith, nameFrom, nameTo. Returns every match in one page (`nextCursor` is null); limit is ignored. */
  ids?: string[] | undefined;
  /** Return only the entities with these full names (case-insensitive, including parent names separated by colons). Cannot be combined with ids, status, updatedAfter, updatedBefore, nameStartsWith, nameContains, nameEndsWith, nameFrom, nameTo. Returns every match in one page (`nextCursor` is null); limit is ignored. */
  fullNames?: string[] | undefined;
  /**
   * Maximum number of entities per page, 1 to 150. Ignored with ids, fullNames, which return every match in one page.
   *
   * @defaultValue 150
   */
  limit?: number | undefined;
  /** Filter entities by active state. Defaults to active ones only. Cannot be combined with ids, fullNames. */
  status?: ActiveStatus | undefined;
  /**
   * Return entities changed on or after this date or date-time (QuickBooks local time unless an offset is given). Cannot be combined with ids, fullNames.
   *
   * Accepts YYYY-MM-DD or an ISO 8601 date-time.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  updatedAfter?: string | undefined;
  /**
   * Return entities changed on or before this date or date-time (QuickBooks local time unless an offset is given). Cannot be combined with ids, fullNames.
   *
   * Accepts YYYY-MM-DD or an ISO 8601 date-time.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  updatedBefore?: string | undefined;
  /** Return entities whose name starts with this text (case-insensitive). Cannot be combined with ids, fullNames, nameFrom, nameTo. */
  nameStartsWith?: string | undefined;
  /** Return entities whose name contains this text (case-insensitive). Cannot be combined with ids, fullNames, nameFrom, nameTo. */
  nameContains?: string | undefined;
  /** Return entities whose name ends with this text (case-insensitive). Cannot be combined with ids, fullNames, nameFrom, nameTo. */
  nameEndsWith?: string | undefined;
  /** Return entities whose name sorts at or after this value. Cannot be combined with ids, fullNames, nameStartsWith, nameContains, nameEndsWith. */
  nameFrom?: string | undefined;
  /** Return entities whose name sorts at or before this value. Cannot be combined with ids, fullNames, nameStartsWith, nameContains, nameEndsWith. */
  nameTo?: string | undefined;
  /** Cursor from the previous page's nextCursor. Send it with no other filters to fetch the next page. */
  cursor?: string | undefined;
}

export interface ErrorObject {
  /**
   * Error category. Use it to choose between retrying, fixing the request and asking the end user to act.
   *
   * Open enum: new values can appear without an API version change.
   */
  type: ErrorType;
  /**
   * Stable error code from the error catalog. New codes may be added; a code's meaning never changes.
   *
   * Open enum: new values can appear without an API version change.
   *
   * @example "QBD_MODAL_DIALOG_OPEN"
   */
  code: ErrorCode;
  /** Developer-facing explanation. May include IDs and field paths; never includes secrets. */
  message: string;
  /** A message that is safe to show to the end user. */
  userFacingMessage: string;
  /**
   * HTTP status of the response. Every code defines one; on a request resource it is the status a synchronous call returns for the same error (for example 409 for `REQUEST_CANCELED`, 504 for `REQUEST_EXPIRED`). Nullable for compatibility only.
   *
   * @example 503
   */
  httpStatusCode: number | null;
  /**
   * Native QuickBooks code when one exists: a qbXML statusCode (`"3200"`), an HRESULT (`"0x80040414"`) or a Web Connector code.
   *
   * @example "0x80040414"
   */
  integrationCode: string | null;
  /**
   * The `Daapi-Request-Id` of this response. Include it when contacting support.
   *
   * @example "req_01j9x4m6v4c8k2t7q0r5s3w1zd"
   */
  requestId: string;
  /** Why this error happens. */
  cause: string;
  /** Ordered actions that resolve the error, each with the responsible actor. */
  fixes: ErrorFix[];
  /**
   * Documentation section for this code.
   *
   * @example "https://www.desktopaccountingapi.com/docs/errors/#qbd_modal_dialog_open"
   */
  docsUrl: string;
  /** Repeating the identical request (with the same Idempotency-Key for writes) can succeed without changes. Also sent as the `Daapi-Should-Retry` header. */
  retryable: boolean;
  /**
   * Whether a write took effect: `applied` (QuickBooks confirmed it), `not_applied` (it certainly did not happen), `pending` (sent, still processing), `unknown` (sent, result could not be confirmed) or `not_applicable` (a read).
   *
   * Open enum: new values can appear without an API version change.
   */
  outcome: ErrorOutcome;
  /**
   * Request field, query parameter or header the error refers to, when known.
   *
   * @example "companyName"
   */
  param: string | null;
  /** Code-specific details, documented per code in the error catalog. */
  details: Record<string, unknown>;
}

export interface ErrorFix {
  /**
   * Who can apply the fix.
   *
   * Open enum: new values can appear without an API version change.
   */
  actor: ErrorFixActor;
  /** What to do. */
  action: string;
}

/** Estimate as stored in QuickBooks Desktop. */
export interface Estimate {
  /** QuickBooks-assigned ID of this estimate. */
  id: string;
  /** Type of this object. */
  objectType: "qbd_estimate";
  /**
   * When this estimate was created, as an ISO 8601 date-time with the QuickBooks computer's UTC offset.
   *
   * ISO 8601 date-time with the offset QuickBooks reports.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  createdAt: string;
  /**
   * When this estimate was last changed, as an ISO 8601 date-time with the QuickBooks computer's UTC offset. Whole seconds: a second change within the same second keeps this value, so incremental syncs should overlap `updatedAfter` and deduplicate by `id` and `revisionNumber`.
   *
   * ISO 8601 date-time with the offset QuickBooks reports.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  updatedAt: string;
  /** Current revision of this estimate. Send it unchanged when updating; a stale value is rejected. QuickBooks changes it at most once per second, so a second edit within the same second keeps the same value. This API spaces its own consecutive writes to one object by over a second; edits made elsewhere in the same second are not detected. */
  revisionNumber: string;
  /** Sequential transaction number QuickBooks assigns internally. */
  transactionNumber: number | null;
  /** The customer for this estimate. */
  customer: Reference | null;
  /** The class for this estimate. */
  class: Reference | null;
  /** The document template for this estimate. */
  documentTemplate: Reference | null;
  /**
   * Date of this estimate (YYYY-MM-DD).
   *
   * Date, YYYY-MM-DD.
   *
   * @example "2026-10-05"
   */
  transactionDate: string | null;
  /** Reference number of this estimate, such as an invoice or check number. Case-sensitive. */
  refNumber: string | null;
  /** Billing address for this estimate. */
  billingAddress: Address | null;
  /** Shipping address for this estimate. */
  shippingAddress: Address | null;
  /** Whether this estimate is active. Inactive objects stay in QuickBooks but are hidden from most lists. */
  isActive: boolean | null;
  /** Purchase order number of this estimate. */
  purchaseOrderNumber: string | null;
  /** The terms for this estimate. */
  terms: Reference | null;
  /**
   * Date payment of this estimate is due (YYYY-MM-DD).
   *
   * Date, YYYY-MM-DD.
   *
   * @example "2026-10-05"
   */
  dueDate: string | null;
  /** The sales representative for this estimate. */
  salesRepresentative: Reference | null;
  /** Shipment origin of this estimate. */
  shipmentOrigin: string | null;
  /**
   * Total of all lines before sales tax, as a decimal string.
   *
   * Decimal string (for example "52.75"); the SDK never converts it to a binary float.
   *
   * @example "1250.00"
   */
  subtotal: string | null;
  /** The sales tax item for this estimate. */
  salesTaxItem: Reference | null;
  /**
   * Sales tax rate applied, as a percentage. Percentage as a decimal string: "7.5" means 7.5 %.
   *
   * Decimal string (for example "52.75"); the SDK never converts it to a binary float.
   *
   * @example "7.5"
   */
  salesTaxPercentage: string | null;
  /**
   * Total sales tax, as a decimal string.
   *
   * Decimal string (for example "52.75"); the SDK never converts it to a binary float.
   *
   * @example "1250.00"
   */
  salesTaxTotal: string | null;
  /**
   * Total amount of this estimate as a decimal string.
   *
   * Decimal string (for example "52.75"); the SDK never converts it to a binary float.
   *
   * @example "1250.00"
   */
  totalAmount: string | null;
  /** Currency of this estimate. */
  currency: Reference | null;
  /** Exchange rate from this estimate's currency to the home currency. */
  exchangeRate: number | null;
  /**
   * Total amount in home currency of this estimate. Decimal string with up to 2 decimal places.
   *
   * Decimal string (for example "52.75"); the SDK never converts it to a binary float.
   *
   * @example "1250.00"
   */
  totalAmountInHomeCurrency: string | null;
  /** Internal memo for this estimate; shown in reports, not on printed forms. */
  memo: string | null;
  /** The customer message for this estimate. */
  customerMessage: Reference | null;
  /** Whether this estimate is in the queue of forms to email. */
  isQueuedForEmail: boolean | null;
  /** The sales tax code for this estimate. */
  salesTaxCode: Reference | null;
  /** Built-in "Other" text field on this estimate. */
  otherCustomField: string | null;
  /** Your own UUID for this estimate, stored by QuickBooks so you can match records with your system. */
  externalId: string | null;
  /** Transactions linked to this estimate, such as payments applied to it. */
  linkedTransactions: LinkedTransaction[];
  /** Line items of this estimate. */
  lines: EstimateLine[];
  /** Group lines of this estimate: each expands an item group into its component lines. */
  lineGroups: EstimateLineGroup[];
  /** Custom field values QuickBooks stores on this estimate. */
  customFields: CustomField[];
}

