  /** Whether this purchase order is manually closed. */
  isManuallyClosed: boolean | null;
  /** Whether this purchase order is fully received. */
  isFullyReceived: boolean | null;
  /** Internal memo for this purchase order; shown in reports, not on printed forms. */
  memo: string | null;
  /** Vendor message of this purchase order. */
  vendorMessage: string | null;
  /** Whether this purchase order is in the queue of forms to print. */
  isQueuedForPrint: boolean | null;
  /** Whether this purchase order is in the queue of forms to email. */
  isQueuedForEmail: boolean | null;
  /** Built-in "Other 1" text field on this purchase order. */
  otherCustomField1: string | null;
  /** Built-in "Other 2" text field on this purchase order. */
  otherCustomField2: string | null;
  /** Your own UUID for this purchase order, stored by QuickBooks so you can match records with your system. */
