export interface PurchaseOrderListParams {
  /** Return only the purchase orders with these QuickBooks IDs. Cannot be combined with refNumbers, updatedAfter, updatedBefore, transactionDateFrom, transactionDateTo, transactionDateMacro, vendorIds, accountIds, refNumberStartsWith, refNumberContains, refNumberEndsWith, refNumberFrom, refNumberTo, currencyIds. Returns every match in one page (`nextCursor` is null); limit is ignored. */
  ids?: string[] | undefined;
  /** Return only purchase orders with these reference numbers (case-insensitive). Cannot be combined with ids, updatedAfter, updatedBefore, transactionDateFrom, transactionDateTo, transactionDateMacro, vendorIds, accountIds, refNumberStartsWith, refNumberContains, refNumberEndsWith, refNumberFrom, refNumberTo, currencyIds. Returns every match in one page (`nextCursor` is null); limit is ignored. */
  refNumbers?: string[] | undefined;
  /**
   * Maximum number of purchase orders per page, 1 to 150. Ignored with ids, refNumbers, which return every match in one page.
   *
   * @defaultValue 150
   */
  limit?: number | undefined;
  /**
   * Return purchase orders changed on or after this date or date-time (QuickBooks local time unless an offset is given). Cannot be combined with ids, refNumbers, transactionDateFrom, transactionDateTo, transactionDateMacro.
   *
   * Accepts YYYY-MM-DD or an ISO 8601 date-time.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  updatedAfter?: string | undefined;
  /**
   * Return purchase orders changed on or before this date or date-time (QuickBooks local time unless an offset is given). Cannot be combined with ids, refNumbers, transactionDateFrom, transactionDateTo, transactionDateMacro.
   *
   * Accepts YYYY-MM-DD or an ISO 8601 date-time.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  updatedBefore?: string | undefined;
  /**
   * Return purchase orders dated on or after this date (YYYY-MM-DD). Cannot be combined with ids, refNumbers, updatedAfter, updatedBefore, transactionDateMacro.
   *
   * Date, YYYY-MM-DD.
   */
  transactionDateFrom?: string | undefined;
  /**
   * Return purchase orders dated on or before this date (YYYY-MM-DD). Cannot be combined with ids, refNumbers, updatedAfter, updatedBefore, transactionDateMacro.
   *
   * Date, YYYY-MM-DD.
   */
  transactionDateTo?: string | undefined;
  /** Relative date range such as this_month, used instead of explicit dates. Cannot be combined with ids, refNumbers, updatedAfter, updatedBefore, transactionDateFrom, transactionDateTo. */
  transactionDateMacro?: DateMacro | undefined;
  /** Return only purchase orders linked to these vendor IDs. Cannot be combined with ids, refNumbers. */
  vendorIds?: string[] | undefined;
  /** Return only purchase orders that use these account IDs. Cannot be combined with ids, refNumbers. */
  accountIds?: string[] | undefined;
  /** Return purchase orders whose reference number starts with this text (case-insensitive). Cannot be combined with ids, refNumbers, refNumberFrom, refNumberTo. */
  refNumberStartsWith?: string | undefined;
  /** Return purchase orders whose reference number contains this text (case-insensitive). Cannot be combined with ids, refNumbers, refNumberFrom, refNumberTo. */
  refNumberContains?: string | undefined;
  /** Return purchase orders whose reference number ends with this text (case-insensitive). Cannot be combined with ids, refNumbers, refNumberFrom, refNumberTo. */
  refNumberEndsWith?: string | undefined;
  /** Return purchase orders whose reference number sorts at or after this value. Cannot be combined with ids, refNumbers, refNumberStartsWith, refNumberContains, refNumberEndsWith. */
  refNumberFrom?: string | undefined;
  /** Return purchase orders whose reference number sorts at or before this value. Cannot be combined with ids, refNumbers, refNumberStartsWith, refNumberContains, refNumberEndsWith. */
  refNumberTo?: string | undefined;
  /** Return only purchase orders in these currency IDs. Cannot be combined with ids, refNumbers. */
  currencyIds?: string[] | undefined;
  /**
   * Whether to include line items on each purchase order. Defaults to true.
   *
   * @defaultValue true
   */
  includeLineItems?: boolean | undefined;
  /**
   * Whether to include transactions linked to each purchase order, such as payments.
   *
   * @defaultValue false
   */
  includeLinkedTransactions?: boolean | undefined;
  /** Cursor from the previous page's nextCursor. Send it with no other filters to fetch the next page. */
  cursor?: string | undefined;
}

