export interface ReportCell {
  /** Column this cell belongs to. */
  columnId: string;
  /** Cell value as QuickBooks formats it. */
  value: string | null;
  /** qbXML data type of the value, in snake_case, such as `amttype` or `strtype`. QuickBooks usually types the column rather than each cell, so this is the column's `dataType` unless the cell carries its own. Null only when neither is reported. */
  dataType: string | null;
}

export interface ReportColumn {
  /** Column identifier used by row cells. */
  columnId: string;
  /** What the column holds, such as amount or account. */
  columnType: string | null;
  /** qbXML data type of the column values, in snake_case. */
  dataType: string | null;
  /** Title text per title row. */
  titles: ReportColumnTitle[];
}

export interface ReportColumnTitle {
  /** Title row this text belongs to (1-based). */
  rowNumber: number;
  /** Title text. */
  value: string | null;
}

