export interface ReportRow {
  /**
   * Row kind: `data`, `text`, `subtotal` or `total`.
   *
   * Open enum: new values can appear without an API version change.
   */
  kind: ReportRowKind;
  /** Row position in the report (1-based). */
  rowNumber: number;
  /** Text of a text row; null for other kinds. */
  text: string | null;
  /** What a data, subtotal or total row describes; null for text rows and rows without one. */
  rowDescriptor: ReportRowDescriptor | null;
  /** Cell values of the row; empty for text rows. */
  cells: ReportCell[];
}

export interface ReportRowDescriptor {
  /** Kind of object the row describes, such as account or customer. */
  type: string | null;
  /** Name of that object. */
  value: string | null;
}

