/** Workers' compensation code as stored in QuickBooks Desktop. */
export interface WorkersCompCode {
  /** QuickBooks-assigned ID of this workers' compensation code. */
  id: string;
  /** Type of this object. */
  objectType: "qbd_workers_comp_code";
  /**
   * When this workers' compensation code was created, as an ISO 8601 date-time with the QuickBooks computer's UTC offset.
   *
   * ISO 8601 date-time with the offset QuickBooks reports.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  createdAt: string;
  /**
   * When this workers' compensation code was last changed, as an ISO 8601 date-time with the QuickBooks computer's UTC offset. Whole seconds: a second change within the same second keeps this value, so incremental syncs should overlap `updatedAfter` and deduplicate by `id` and `revisionNumber`.
   *
   * ISO 8601 date-time with the offset QuickBooks reports.
   *
   * @example "2026-10-05T09:14:03-07:00"
   */
  updatedAt: string;
  /** Current revision of this workers' compensation code. Send it unchanged when updating; a stale value is rejected. QuickBooks changes it at most once per second, so a second edit within the same second keeps the same value. This API spaces its own consecutive writes to one object by over a second; edits made elsewhere in the same second are not detected. */
  revisionNumber: string;
  /** Name of this workers' compensation code, unique within its parent level. */
  name: string | null;
  /** Whether this workers' compensation code is active. Inactive objects stay in QuickBooks but are hidden from most lists. */
  isActive: boolean | null;
  /** Description of this workers' compensation code. */
  description: string | null;
  /**
   * Current rate of this workers' compensation code. Decimal string with up to 5 decimal places.
   *
   * Decimal string (for example "52.75"); the SDK never converts it to a binary float.
   *
   * @example "19.99"
   */
  currentRate: string | null;
  /**
   * Current effective date (YYYY-MM-DD).
   *
   * Date, YYYY-MM-DD.
   *
   * @example "2026-10-05"
   */
  currentEffectiveDate: string | null;
  /**
   * Next rate of this workers' compensation code. Decimal string with up to 5 decimal places.
   *
   * Decimal string (for example "52.75"); the SDK never converts it to a binary float.
   *
   * @example "19.99"
   */
  nextRate: string | null;
  /**
   * Next effective date (YYYY-MM-DD).
   *
   * Date, YYYY-MM-DD.
   *
   * @example "2026-10-05"
   */
  nextEffectiveDate: string | null;
  /** Rate history entries for this workers' compensation code. */
  rateHistory: RateHistory[];
}

