/** The result type of one `qbd.batch` member `Q`: the {@link BatchResult} variant with the same `operationId`. */
export type BatchResultFor<Q extends { operationId: string }> = Extract<BatchResult, { operationId: Q["operationId"] }>;

/** The `qbd.batch` response for the request members `R`, with `results[i]` typed by `requests[i]`. */
export type BatchFor<R extends readonly { operationId: string }[]> = Omit<Batch, "results"> & {
  results: { -readonly [K in keyof R]: BatchResultFor<R[K]> };
};
